CREATE TABLE `solution_list_items` (`id` INT NOT NULL AUTO_INCREMENT, `solution_id` INT NOT NULL, `section` VARCHAR(40) NOT NULL, `text` VARCHAR(300) NOT NULL, `sort_order` INT NOT NULL DEFAULT 0, PRIMARY KEY (`id`), INDEX `solution_list_items_solution_id_section_sort_order_idx` (`solution_id`, `section`, `sort_order`), CONSTRAINT `solution_list_items_solution_id_fkey` FOREIGN KEY (`solution_id`) REFERENCES `solutions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;